bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -i -w /opt/videobot "$cid" node --input-type=module - <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
import {myVideosPanel} from './src/telegram/creatorUi.mjs';
import {createPostgresListingStore} from './src/sales/pgListings.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:2});
const out=createCreatorTelegramFetch(fetch);
const api=createTelegramBotApi({token:readFileSync('/run/secrets/videobot_telegram_token','utf8').trim(),fetchImpl:out.fetch,timeoutMs:20000,baseUrl:process.env.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org'});
const c=await pool.connect();
try{
 await c.query('BEGIN');
 const q=await c.query("SELECT s.* FROM videobot_creator_sessions s JOIN videobot_listings l ON l.seller_user_id=s.owner_user_id WHERE l.listing_id=$1 FOR UPDATE OF s",['v26nov24invoice']);
 if(q.rows.length!==1)throw Error('SESSION_NOT_UNIQUE');
 const row=q.rows[0],state=row.state,owner=Number(row.owner_user_id),revision=Number(row.revision);
 const ref=state.pendingVideoDraft??(state.draft?.listingId?{listingId:state.draft.listingId,revision:state.draft.revision}:null);
 if(state.publishing!=='needs_reconcile'||!ref)throw Error('SESSION_CHANGED_RECHECK');
 const r=await c.query("SELECT l.status,r.status AS receipt_status,r.paid_message_id IS NOT NULL AS paid,cardinality(r.free_message_ids) AS free_count FROM videobot_listings l JOIN videobot_post_receipts r ON r.listing_id=l.listing_id AND r.revision=$3 WHERE l.seller_user_id=$1 AND l.listing_id=$2",[owner,ref.listingId,ref.revision]);
 const v=r.rows[0];
 const u=await c.query("SELECT count(*)::int AS n FROM videobot_post_receipts r JOIN videobot_listings l ON l.listing_id=r.listing_id WHERE l.seller_user_id=$1 AND r.status<>'sent'",[owner]);
 if(r.rows.length!==1||v.status!=='published'||v.receipt_status!=='sent'||!v.paid||![2,3].includes(v.free_count)||u.rows[0].n!==0)throw Error('PREVIOUS_PUBLICATION_NOT_VERIFIED');
 const next={...state,publishing:null,pendingVideoDraft:null,draft:null,originalDraft:null,previewMessageId:null,albumMessageId:null,waiting:null,field:null,screen:'my_videos',page:0};
 const listings=await createPostgresListingStore(pool).listByOwner(owner);
 const panel=myVideosPanel({sellerId:String(owner),listings,page:0,revision:revision+1});
 const sent=await api('sendMessage',{chat_id:owner,...panel,disable_notification:true});
 if(sent?.chat?.id!==owner||!Number.isSafeInteger(sent.message_id)||sent.text!==panel.text||!sent.reply_markup?.inline_keyboard?.flat().some(x=>x.callback_data==='menu:listing'))throw Error('MENU_ACK_NOT_VERIFIED');
 const w=await c.query("UPDATE videobot_creator_sessions SET revision=$2,screen_message_id=$3,state=$4::jsonb,updated_at=NOW() WHERE owner_user_id=$1 AND revision=$5 RETURNING revision,state->>'publishing' AS publishing",[owner,revision+1,sent.message_id,JSON.stringify(next),revision]);
 if(w.rowCount!==1||w.rows[0].publishing!==null)throw Error('SESSION_REPAIR_NOT_DURABLE');
 await c.query('COMMIT');
 console.log('EXACT_OLD_RECEIPT_VERIFIED_NEW_POST_LOCK_CLEARED_AND_MENU_ACK=PASS');
}catch(e){await c.query('ROLLBACK').catch(()=>{});console.log('REPAIR',String(e.message).slice(0,150));process.exitCode=70;}
finally{c.release();await pool.end();await out.close()}
JS
